#!/usr/bin/env python3
"""Commit-sized metadata only: no commercial world/resource/frame payloads."""
import argparse,hashlib,json,subprocess,time
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
ap=argparse.ArgumentParser();ap.add_argument('map');a=ap.parse_args();base=ROOT/'artifacts/local/ultimate-speedruns'/a.map;recording=base/'full-rate';out=ROOT/'artifacts/ultimate-speedruns'/a.map;out.mkdir(exist_ok=True)
r=json.loads((recording/'evm.json').read_text());v=json.loads((recording/'verification.json').read_text());m=json.loads((recording/'frame-manifest.json').read_text());n=json.loads((base/'native-result.json').read_text());s=json.loads((base/'source.json').read_text())
assert r['pass'] and v['evidenceVerified'] and v['recordingComplete'] and v['mediaVerified']
pixel=json.loads((recording/'pixel-domain.json').read_text());assert pixel['pass_'] and pixel['recordingComplete'] and pixel['frames']==len(r['frames']) and pixel['sourceReportSha256']==sha(recording/'evm.json')
comparisons=v['nativePixelComparisons'];samples=json.loads((recording/'virtual-samples.json').read_text())
result=dict(map=a.map,profile='classic-ultimate-doom-1.9',experimentalMemoryProfile='virtual',demo=dict(author=s['author'],originalName=s['originalName'],URL=s['downloadUrl'],SHA256=s['demoSha256']),IWAD=dict(MD5='c4fe9fd920207691a9f493668e0a2083',SHA256=n['wadSha256']),nativeReplay=dict(tics=n['executedTics'],observations=n['executedTics']+1,allAllocationProfilesExact=n['allProfilesExact'],statesSHA256=n['statesSha256'],referenceProfile=r.get('nativeProfile','four-allocation-profiles')),EVMGameplay=dict(tics=r['verifiedTics'],observations=v['gameplayObservations'],allSnapshotsExact=True,exit=r['exit']),frames=dict(rendered=len(r['frames']),O2Comparisons=len(comparisons),O2Equal=sum(c['O2Equal'] for c in comparisons),allDeclaredNativeProfilesEqual=sum(len(c['equalProfiles'])==3 for c in comparisons),virtualSampleUses=v['virtualSampleUses'],virtualDerivedDestinations=v['virtualDerivedDestinations'],nativeCommonExactWithoutVirtualSamples=sum(len(c['equalProfiles'])==3 and c['virtualSamples']==0 for c in comparisons)),gas=dict(gameplay=r['totalReplayGas'],capture=r['totalCaptureGas'],renderer=r['totalRendererGas'],totalVerifiedRecording=r['totalGasIncludingStartupAndDeployment']),runtime=dict(serverArgs=r['serverArgs'],gasBudget=r['executionBudget'],startedUTC=r['startedUTC'],endedUTC=r['endedUTC'],successfulReplayRPCSeconds=r['replayTransactionElapsedMs']/1000,captureRPCSeconds=r['captureTransactionElapsedMs']/1000,replaySessionSeconds=r.get('replayElapsedMs',0)/1000,resumeSessions=r.get('resumeSessions',[])),media=dict(MP4=str((recording/m['media']['mp4']).relative_to(ROOT)),SHA256=m['media']['mp4Sha256'],fps=35,encodedFrames=m['media']['encodedFrames'],seconds=m['media']['gameDurationSeconds']),unresolvedFailure=None,limitations='Finite native-profile comparisons only. Virtual-derived pixels remain deterministic extensions even when equal to native. Observational renders use a temporary copy; no continuously persisted render history or production UI acceptance.',sourceHashes=r['sourceHashes'],compiler=r['compiler'],abiSHA256=r['abiSha256'],resourceIdentity=r['resourceIdentity'],recordedSourceCommit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip())
result['supportedPixelDomain']={k:v for k,v in pixel.items() if k!='rows'}
(out/'result.json').write_text(json.dumps(result,indent=2)+'\n');(out/'virtual-samples.json').write_text(json.dumps(samples,indent=2)+'\n')
files=[]
for p in [recording/'evm.json',recording/'verification.json',recording/'frame-manifest.json',recording/'virtual-samples.json',recording/'pixel-domain.json',base/'native-result.json',base/'native-full/native-frames.json',*(recording.glob('evm.*-receipts.json.gz'))]:
 if p.exists():files.append(dict(path=str(p.relative_to(ROOT)),bytes=p.stat().st_size,SHA256=sha(p)))
files+= [dict(path=str(p.relative_to(ROOT)),bytes=p.stat().st_size,SHA256=sha(p)) for p in [out/'result.json',out/'virtual-samples.json']]
(out/'evidence-manifest.json').write_text(json.dumps(dict(map=a.map,files=files,commercialPayloadsLocalOnly=True,MP4LocalOnly=True,UTC=time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime())),indent=2)+'\n');print(json.dumps(result['frames']))
